    // TODO: implement
    return 0;
}

int main() {
    char line[100000];
    fgets(line, sizeof(line), stdin);
    int * nums = malloc(sizeof(int) * 100001);
    int n = 0;
    char * p = strtok(line, " \t\r\n");
    while (p) {
        nums[n++] = atoi(p);
        p = strtok(NULL, " \t\r\n");
    }
    int target;
