('913495f6-ce90-4bb8-aebe-04dd7dbf47ac', '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode * left, * right;
}
TreeNode;

static TreeNode * newNode(int v) {
    TreeNode * n = (TreeNode * ) malloc(sizeof(TreeNode));
    n - > val = v;
    n - > left = n - > right = NULL;
    return n;
}

static TreeNode * buildTree(char * line) {
    static char * toks[100005];
    int nt = 0;
    char * p = strtok(line, " ");
    while (p && nt < 100005) {
        toks[nt++] = p;
        p = strtok(NULL, " ");
    }
    if (nt == 0 || strcmp(toks[0], "null") == 0) return NULL;
    TreeNode * root = newNode(atoi(toks[0]));
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    int i = 1;
    while (qh < qt && i < nt) {
        TreeNode * node = q[qh++];
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > left = newNode(atoi(toks[i]));
            q[qt++] = node - > left;
        }
        i++;
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > right = newNode(atoi(toks[i]));
            q[qt++] = node - > right;
        }
        i++;
    }
    return root;
}

/* Print each level on its own line, deepest first, values space-separated. */
void levelOrderBottom(TreeNode * root) {
    /* TODO */
}

int main() {
    char line[1000005];
    if (fgets(line, sizeof(line), stdin) == NULL) line[0] = ''\0'';
    line[strcspn(line, "\r\n")] = ''\0'';
    TreeNode * root = buildTree(line);
    levelOrderBottom(root);
    return 0;
}'),
('555ed883-6017-4d12-bead-9be5bec69501', 'package main

import(
    "fmt"
    "io"
    "os"
    "strconv"
    "strings"
)

type TreeNode struct {
    Val int
    Left * TreeNode
    Right * TreeNode
}

func buildTree(line string) * TreeNode {
    toks: = strings.Fields(line)
    if len(toks) == 0 || toks[0] == "null" {
        return nil
    }
    v,
    _: = strconv.Atoi(toks[0])
    root: = & TreeNode {
        Val: v
    }
    queue: = [] * TreeNode {
        root
    }
    i: = 1
    for len(queue) > 0 && i < len(toks) {
        node: = queue[0]
        queue = queue[1: ]
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Left = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Left)
        }
        i++
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Right = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Right)
        }
        i++
    }
    return root
}

func levelOrderBottom(root * TreeNode)[][] int {
    // TODO
    return [][] int {}
}

func main() {
    data,
    _: = io.ReadAll(os.Stdin)
    lines: = strings.Split(string(data), "\n")
    root: = buildTree(lines[0])
    var out[] string
    for _,
    lvl: = range levelOrderBottom(root) {
        strs: = make([] string, len(lvl))
        for i,
        v: = range lvl {
            strs[i] = strconv.Itoa(v)
        }
        out = append(out, strings.Join(strs, " "))
    }
    fmt.Println(strings.Join(out, "\n"))
}'),
