('b514ff71-21ff-4ede-8cce-68628d80b5a4', '#include <bits/stdc++.h>

using namespace std;

struct TreeNode {
    int val;
    TreeNode * left, * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};

static TreeNode * buildTree(string line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty() || toks[0] == "null") return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size() && toks[i] != "null") {
            node - > left = new TreeNode(stoi(toks[i]));
            q.push(node - > left);
        }
        i++;
        if (i < toks.size() && toks[i] != "null") {
            node - > right = new TreeNode(stoi(toks[i]));
            q.push(node - > right);
        }
        i++;
    }
    return root;
}

vector < vector < int >> levelOrderBottom(TreeNode * root) {
    // TODO
    return {};
}

int main() {
    string line;
    getline(cin, line);
    TreeNode * root = buildTree(line);
    for (auto & lvl: levelOrderBottom(root)) {
        for (size_t i = 0; i < lvl.size(); i++) cout << lvl[i] << (i + 1 < lvl.size() ? " " : "");
        cout << "\n";
    }
    return 0;
}'),
('c3eb02d3-d9d3-4a42-8cb4-a0e79460f920', 'import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) {
            val = v;
        }
    }
    static TreeNode buildTree(String line) {
        if (line == null) return null;
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0 || toks[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        java.util.ArrayDeque < TreeNode > q = new java.util.ArrayDeque < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length && !toks[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.left);
            }
            i++;
            if (i < toks.length && !toks[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static List < List < Integer >> levelOrderBottom(TreeNode root) {
        // TODO
        return new ArrayList < > ();
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        TreeNode root = buildTree(line);
        StringBuilder sb = new StringBuilder();
        for (List < Integer > lvl: levelOrderBottom(root)) {
            for (int i = 0; i < lvl.size(); i++) sb.append(lvl.get(i)).append(i + 1 < lvl.size() ? " " : "");
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}'),
('d3769707-244e-4931-8107-d80d01d4ee5f', 'import sys
from collections import deque
class TreeNode:
    def __init__(self,val=0,left=None,right=None):
        self.val=val; self.left=left; self.right=right; self.next=None
def build_tree(tokens):
    if not tokens or tokens[0]=="null": return None
    root=TreeNode(int(tokens[0])); q=deque([root]); i=1
    while q and i<len(tokens):
        node=q.popleft()
        if i<len(tokens) and tokens[i]!="null":
            node.left=TreeNode(int(tokens[i])); q.append(node.left)
        i+=1
        if i<len(tokens) and tokens[i]!="null":
            node.right=TreeNode(int(tokens[i])); q.append(node.right)
        i+=1
    return root
def serialize(root):
    if not root: return ""
    q=deque([root]); out=[]
    while q:
        node=q.popleft()
        if node: out.append(str(node.val)); q.append(node.left); q.append(node.right)
        else: out.append("null")
    while out and out[-1]=="null": out.pop()
    return " ".join(out)

