    root=TreeNode(int(tokens[0])); q=deque([root]); i=1
    while q and i<len(tokens):
        node=q.popleft()
        if i<len(tokens) and tokens[i]!="null":
            node.left=TreeNode(int(tokens[i])); q.append(node.left)
        i+=1
        if i<len(tokens) and tokens[i]!="null":
            node.right=TreeNode(int(tokens[i])); q.append(node.right)
        i+=1
    return root
def serialize(root):
    if not root: return ""
    q=deque([root]); out=[]
    while q:
        node=q.popleft()
        if node: out.append(str(node.val)); q.append(node.left); q.append(node.right)
        else: out.append("null")
