#include <stdlib.h>

#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode * left, * right;
}
TreeNode;
static TreeNode * newNode(int v) {
    TreeNode * n = (TreeNode * ) malloc(sizeof(TreeNode));
    n - > val = v;
    n - > left = n - > right = NULL;
    return n;
}
static TreeNode * buildTree(char * line) {
    static char * toks[100005];
    int nt = 0;
    char * p = strtok(line, " ");
    while (p && nt < 100005) {
        toks[nt++] = p;
        p = strtok(NULL, " ");
    }
    if (nt == 0 || strcmp(toks[0], "null") == 0) return NULL;
    TreeNode * root = newNode(atoi(toks[0]));
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    int i = 1;
    while (qh < qt && i < nt) {
        TreeNode * node = q[qh++];
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > left = newNode(atoi(toks[i]));
            q[qt++] = node - > left;
        }
        i++;
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > right = newNode(atoi(toks[i]));
            q[qt++] = node - > right;
        }
        i++;
    }
    return root;
}

/* serialize into out buffer (level order, trailing nulls trimmed, space-separated) */
static void serialize(TreeNode * root, char * out) {
    out[0] = ''\0'';
    if (!root) {
        return;
    }
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    static char * parts[200005];
    int np = 0;
    static char bufs[200005][14];
    while (qh < qt) {
        TreeNode * n = q[qh++];
        if (n) {
            sprintf(bufs[np], "%d", n - > val);
            parts[np] = bufs[np];
            np++;
            q[qt++] = n - > left;
            q[qt++] = n - > right;
        } else {
            strcpy(bufs[np], "null");
            parts[np] = bufs[np];
            np++;
        }
    }
    while (np > 0 && strcmp(parts[np - 1], "null") == 0) np--;
    for (int i = 0; i < np; i++) {
        strcat(out, parts[i]);
        if (i + 1 < np) strcat(out, " ");
    }
}

