('7dc761c4-044a-4435-b6d3-f6d207861b4f', '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode * left, * right;
}
TreeNode;

static TreeNode * newNode(int v) {
    TreeNode * n = (TreeNode * ) malloc(sizeof(TreeNode));
    n - > val = v;
    n - > left = n - > right = NULL;
    return n;
}

static TreeNode * buildTree(char * line) {
    static char * toks[100005];
    int nt = 0;
    char * p = strtok(line, " ");
    while (p && nt < 100005) {
        toks[nt++] = p;
        p = strtok(NULL, " ");
    }
    if (nt == 0 || strcmp(toks[0], "null") == 0) return NULL;
    TreeNode * root = newNode(atoi(toks[0]));
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    int i = 1;
    while (qh < qt && i < nt) {
        TreeNode * node = q[qh++];
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > left = newNode(atoi(toks[i]));
            q[qt++] = node - > left;
        }
        i++;
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > right = newNode(atoi(toks[i]));
            q[qt++] = node - > right;
        }
        i++;
    }
    return root;
}

/* Report each qualifying path via emit(path, len). Any order is fine; the harness sorts. */
static void emit(int * path, int len);

void pathSum(TreeNode * root, int target) {
    /* TODO: for each root-to-leaf path summing to target, call emit(path, len) */
}

/* ---- harness: collect, sort, print ---- */
static int ** buf;
static int * lens;
static int cap, cnt;
static int cmp_p(const void * a,
    const void * b) {
    int ia = * (const int * ) a, ib = * (const int * ) b, m = lens[ia] < lens[ib] ? lens[ia] : lens[ib];
    for (int i = 0; i < m; i++) {
        if (buf[ia][i] != buf[ib][i]) return buf[ia][i] - buf[ib][i];
    }
    return lens[ia] - lens[ib];
}
static void emit(int * path, int len) {
    if (cnt == cap) {
        cap = cap ? cap * 2 : 16;
        buf = realloc(buf, cap * sizeof(int * ));
        lens = realloc(lens, cap * sizeof(int));
    }
    int * c = malloc(len * sizeof(int));
    memcpy(c, path, len * sizeof(int));
    buf[cnt] = c;
    lens[cnt] = len;
    cnt++;
}
int main() {
    char line[1000005];
    if (fgets(line, sizeof(line), stdin) == NULL) line[0] = ''\0'';
    line[strcspn(line, "\r\n")] = ''\0'';
    TreeNode * root = buildTree(line);
    int target;
    scanf("%d", & target);
    pathSum(root, target);
    int * idx = malloc((cnt > 0 ? cnt : 1) * sizeof(int));
    for (int i = 0; i < cnt; i++) idx[i] = i;
    qsort(idx, cnt, sizeof(int), cmp_p);
    for (int i = 0; i < cnt; i++) {
        int k = idx[i];
        for (int j = 0; j < lens[k]; j++) printf("%d%s", buf[k][j], j + 1 < lens[k] ? " " : "");
        printf("\n");
    }
    return 0;
}'),
