    "strings"
)

type TreeNode struct {
    Val int
    Left * TreeNode
    Right * TreeNode
}

func buildTree(line string) * TreeNode {
    toks: = strings.Fields(line)
    if len(toks) == 0 || toks[0] == "null" {
        return nil
    }
    v,
    _: = strconv.Atoi(toks[0])
    root: = & TreeNode {
        Val: v
    }
    queue: = [] * TreeNode {
        root
    }
    i: = 1
    for len(queue) > 0 && i < len(toks) {
        node: = queue[0]
        queue = queue[1: ]
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Left = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Left)
        }
        i++
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Right = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Right)
        }
        i++
    }
    return root
}

func pathSum(root * TreeNode, target int)[][] int {
    // TODO
    return [][] int {}
}

func main() {
    data,
    _: = io.ReadAll(os.Stdin)
    lines: = strings.Split(string(data), "\n")
    root: = buildTree(lines[0])
    target,
    _: = strconv.Atoi(strings.TrimSpace(lines[1]))
    res: = pathSum(root, target)
    for _,
    p: = range res {
        _ = p
    }
    // sort
    for i: = 0;i < len(res);i++{
        for j: = i + 1;j < len(res);j++{
            a,
            b: = res[i],
            res[j]
            less: = false
            decided: = false
            m: = len(a)
            if len(b) < m {
                m = len(b)
            }
            for k: = 0;k < m;k++{
                if a[k] != b[k] {
                    less = a[k] < b[k]
                    decided = true
                    break
                }
            }
            if !decided {
                less = len(a) < len(b)
            }
            if !less {
                res[i], res[j] = res[j], res[i]
            }
        }
    }
    var out[] string
    for _,
    p: = range res {
        strs: = make([] string, len(p))
        for i,
        v: = range p {
            strs[i] = strconv.Itoa(v)
        }
        out = append(out, strings.Join(strs, " "))
    }
    fmt.Println(strings.Join(out, "\n"))
}'),
