from collections import deque
class TreeNode:
    def __init__(self,val=0,left=None,right=None):
        self.val=val; self.left=left; self.right=right; self.next=None
def build_tree(tokens):
    if not tokens or tokens[0]=="null": return None
    root=TreeNode(int(tokens[0])); q=deque([root]); i=1
    while q and i<len(tokens):
        node=q.popleft()
        if i<len(tokens) and tokens[i]!="null":
            node.left=TreeNode(int(tokens[i])); q.append(node.left)
        i+=1
        if i<len(tokens) and tokens[i]!="null":
            node.right=TreeNode(int(tokens[i])); q.append(node.right)
        i+=1
    return root
def serialize(root):
    if not root: return ""
    q=deque([root]); out=[]
    while q:
        node=q.popleft()
        if node: out.append(str(node.val)); q.append(node.left); q.append(node.right)
        else: out.append("null")
    while out and out[-1]=="null": out.pop()
    return " ".join(out)

def pathSum(root, target):
