('ece91179-367c-4939-a7ae-c588b5cfc97c', '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

typedef struct Node {
    int val;
    struct Node * left, * right, * next;
}
Node;

static Node * newNode(int v) {
    Node * n = (Node * ) malloc(sizeof(Node));
    n - > val = v;
    n - > left = n - > right = n - > next = NULL;
    return n;
}

static Node * buildTree(char * line) {
    static char * toks[100005];
    int nt = 0;
    char * p = strtok(line, " ");
    while (p && nt < 100005) {
        toks[nt++] = p;
        p = strtok(NULL, " ");
    }
    if (nt == 0 || strcmp(toks[0], "null") == 0) return NULL;
    Node * root = newNode(atoi(toks[0]));
    static Node * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    int i = 1;
    while (qh < qt && i < nt) {
        Node * node = q[qh++];
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > left = newNode(atoi(toks[i]));
            q[qt++] = node - > left;
        }
        i++;
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > right = newNode(atoi(toks[i]));
            q[qt++] = node - > right;
        }
        i++;
    }
    return root;
}
static void outputNext(Node * root) {
    Node * start = root;
    while (start) {
        Node * node = start;
        Node * firstChild = NULL;
        int first = 1;
        while (node) {
            printf("%s%d", first ? "" : " ", node - > val);
            first = 0;
            if (firstChild == NULL) {
                if (node - > left) firstChild = node - > left;
                else if (node - > right) firstChild = node - > right;
            }
            node = node - > next;
        }
        printf(" #\n");
        start = firstChild;
    }
}

Node * connect(Node * root) {
    /* TODO: set each node''s next pointer to its right neighbour on the same level */
    return root;
}

int main() {
    char line[1000005];
    if (fgets(line, sizeof(line), stdin) == NULL) line[0] = ''\0'';
    line[strcspn(line, "\r\n")] = ''\0'';
    Node * root = connect(buildTree(line));
    if (root == NULL) {
        printf("\n");
        return 0;
    }
    outputNext(root);
    return 0;
}'),
