type Node struct {
    Val int
    Left * Node
    Right * Node
    Next * Node
}

func buildTree(line string) * Node {
    toks: = strings.Fields(line)
    if len(toks) == 0 || toks[0] == "null" {
        return nil
    }
    v,
    _: = strconv.Atoi(toks[0])
    root: = & Node {
        Val: v
    }
    queue: = [] * Node {
        root
    }
    i: = 1
    for len(queue) > 0 && i < len(toks) {
        node: = queue[0]
        queue = queue[1: ]
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Left = & Node {
                Val: cv
            }
            queue = append(queue, node.Left)
        }
        i++
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Right = & Node {
                Val: cv
            }
            queue = append(queue, node.Right)
        }
        i++
    }
    return root
}
func outputNext(root * Node) string {
    var lines[] string
    start: = root
    for start != nil {
        node: = start
        var firstChild * Node
        var vals[] string
        for node != nil {
            vals = append(vals, strconv.Itoa(node.Val))
            if firstChild == nil {
                if node.Left != nil {
                    firstChild = node.Left
                } else if node.Right != nil {
                    firstChild = node.Right
                }
            }
            node = node.Next
        }
        lines = append(lines, strings.Join(vals, " ") + " #")
        start = firstChild
    }
    return strings.Join(lines, "\n")
}

func connect(root * Node) * Node {
