('a3d5991c-5854-49ed-8601-43b5f3d72650', 'package main

import(
    "fmt"
    "io"
    "os"
    "strconv"
    "strings"
)

type TreeNode struct {
    Val int
    Left * TreeNode
    Right * TreeNode
}

func buildTree(line string) * TreeNode {
    toks: = strings.Fields(line)
    if len(toks) == 0 || toks[0] == "null" {
        return nil
    }
    v,
    _: = strconv.Atoi(toks[0])
    root: = & TreeNode {
        Val: v
    }
    queue: = [] * TreeNode {
        root
    }
    i: = 1
    for len(queue) > 0 && i < len(toks) {
        node: = queue[0]
        queue = queue[1: ]
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Left = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Left)
        }
        i++
        if i < len(toks) && toks[i] != "null" {
            cv,
            _: = strconv.Atoi(toks[i])
            node.Right = & TreeNode {
                Val: cv
            }
            queue = append(queue, node.Right)
        }
        i++
    }
    return root
}

func serialize(root * TreeNode) string {
    if root == nil {
        return ""
    }
    queue: = [] * TreeNode {
        root
    }
    var parts[] string
    for len(queue) > 0 {
        n: = queue[0]
        queue = queue[1: ]
        if n != nil {
            parts = append(parts, strconv.Itoa(n.Val))
            queue = append(queue, n.Left, n.Right)
        } else {
            parts = append(parts, "null")
        }
    }
    end: = len(parts)
    for end > 0 && parts[end - 1] == "null" {
        end--
    }
    return strings.Join(parts[: end], " ")
}

func upsideDownBinaryTree(root * TreeNode) * TreeNode {
    // TODO
    return root
}

func main() {
    data,
    _: = io.ReadAll(os.Stdin)
    lines: = strings.Split(string(data), "\n")
    root: = upsideDownBinaryTree(buildTree(lines[0]))
    fmt.Println(serialize(root))
}'),
