function buildTree(line: string): TreeNode | null {
    const toks = line.trim() === "" ? [] : line.trim().split(/\s+/);
    if (toks.length === 0 || toks[0] === "null") return null;
    const root = new TreeNode(parseInt(toks[0]));
    const q: (TreeNode | null)[] = [root];
    let i = 1;
    while (q.length && i < toks.length) {
        const node = q.shift() as TreeNode;
        if (i < toks.length && toks[i] !== "null") {
            node.left = new TreeNode(parseInt(toks[i]));
            q.push(node.left);
        }
        i++;
        if (i < toks.length && toks[i] !== "null") {
            node.right = new TreeNode(parseInt(toks[i]));
            q.push(node.right);
        }
        i++;
    }
    return root;
}

function serialize(root: TreeNode | null): string {
    if (!root) return "";
    const q: (TreeNode | null)[] = [root];
    const parts: string[] = [];
    while (q.length) {
        const n = q.shift();
        if (n) {
            parts.push(String(n.val));
            q.push(n.left);
            q.push(n.right);
        } else parts.push("null");
    }
    while (parts.length && parts[parts.length - 1] === "null") parts.pop();
    return parts.join(" ");
}

