    return nullptr;
}

int main() {
    int n;
    cin >> n;
    vector < int > vals(n);
    for (auto & x: vals) cin >> x;
    TreeNode * root = sortedListToBST(vals, 0, n - 1);
    cout << serialize(root) << endl;
    return 0;
}'),
('d180f448-1fa7-49bb-b25a-85d0197f7a5f', 'import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) {
            val = v;
        }
    }
    static TreeNode buildTree(String line) {
        if (line == null) return null;
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0 || toks[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        java.util.ArrayDeque < TreeNode > q = new java.util.ArrayDeque < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length && !toks[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.left);
            }
            i++;
            if (i < toks.length && !toks[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }
    static String serialize(TreeNode root) {
        if (root == null) return "";
        java.util.ArrayDeque < TreeNode > q = new java.util.ArrayDeque < > ();
        q.add(root);
        java.util.List < String > parts = new java.util.ArrayList < > ();
        while (!q.isEmpty()) {
            TreeNode n = q.poll();
            if (n != null) {
                parts.add(Integer.toString(n.val));
                q.add(n.left);
                q.add(n.right);
            } else parts.add("null");
        }
        int end = parts.size();
        while (end > 0 && parts.get(end - 1).equals("null")) end--;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < end; i++) {
            sb.append(parts.get(i));
            if (i + 1 < end) sb.append(" ");
