    root=TreeNode(int(tokens[0])); q=deque([root]); i=1
    while q and i<len(tokens):
        node=q.popleft()
        if i<len(tokens) and tokens[i]!="null":
            node.left=TreeNode(int(tokens[i])); q.append(node.left)
        i+=1
        if i<len(tokens) and tokens[i]!="null":
