/* Nodes are labeled 1..n. adj[i] holds the neighbor labels of node i (adjCount[i] of them).
   Build the clone and fill outAdj/outCount for the clone (1-indexed, neighbors sorted ascending). */
void cloneGraph(int n, int ** adj, int * adjCount, int ** outAdj, int * outCount) {
    /* TODO */
}

static int cmp(const void * a,
    const void * b) {
    return ( * (int * ) a) - ( * (int * ) b);
}

int main() {
    int n;
    if (scanf("%d", & n) != 1) n = 0;
    int c = getchar(); /* consume rest of line */
    int ** adj = (int ** ) malloc((n + 1) * sizeof(int * ));
    int * adjCount = (int * ) calloc(n + 1, sizeof(int));
    for (int i = 1; i <= n; i++) {
        char line[100005];
        if (fgets(line, sizeof(line), stdin) == NULL) line[0] = ''\0'';
        int cap = 8, cnt = 0;
        int * arr = (int * ) malloc(cap * sizeof(int));
        char * p = strtok(line, " \t\r\n");
        while (p) {
            if (cnt == cap) {
                cap *= 2;
                arr = realloc(arr, cap * sizeof(int));
            }
            arr[cnt++] = atoi(p);
            p = strtok(NULL, " \t\r\n");
        }
        adj[i] = arr;
        adjCount[i] = cnt;
    }
    int ** outAdj = (int ** ) malloc((n + 1) * sizeof(int * ));
    int * outCount = (int * ) calloc(n + 1, sizeof(int));
    cloneGraph(n, adj, adjCount, outAdj, outCount);
    for (int i = 1; i <= n; i++) {
        qsort(outAdj[i], outCount[i], sizeof(int), cmp);
        for (int j = 0; j < outCount[i]; j++) printf("%d%s", outAdj[i][j], j + 1 < outCount[i] ? " " : "");
        printf("\n");
    }
    return 0;
}'),
