    static List < List < Integer >> cloneGraph(int n, List < List < Integer >> adj) {
        // TODO
        return new ArrayList < > ();
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        List < List < Integer >> adj = new ArrayList < > ();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList < > ());
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            if (line != null && !line.trim().isEmpty())
                for (String t: line.trim().split("\\s+")) adj.get(i).add(Integer.parseInt(t));
        }
        List < List < Integer >> res = cloneGraph(n, adj);
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            List < Integer > nb = (i < res.size()) ? new ArrayList < > (res.get(i)) : new ArrayList < > ();
            Collections.sort(nb);
            for (int j = 0; j < nb.size(); j++) sb.append(nb.get(j)).append(j + 1 < nb.size() ? " " : "");
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
