('b17ae8b8-20d1-4367-8116-0ab13f66da2b', 'import sys
from collections import deque
class Node:
    def __init__(self,val): self.val=val; self.neighbors=[]
def cloneGraph(node):
    # TODO: return a deep copy of the connected graph reachable from node
    return None
if __name__=="__main__":
    d=sys.stdin.read().split("\n")
    n=int(d[0])
    nodes={i:Node(i) for i in range(1,n+1)}
    adj={}
    for i in range(1,n+1):
        nb=list(map(int,d[i].split())) if d[i].strip() else []
        adj[i]=nb
        for j in nb: nodes[i].neighbors.append(nodes[j])
    if n==0: print(""); sys.exit()
    clone=cloneGraph(nodes[1])
    # BFS the clone, serialize adjacency by val
    seen={}; q=deque([clone]); seen[clone.val]=clone
    while q:
        cur=q.popleft()
        for nb in cur.neighbors:
            if nb.val not in seen: seen[nb.val]=nb; q.append(nb)
    out=[]
    for v in range(1,n+1):
        if v in seen:
            out.append(" ".join(map(str,sorted(x.val for x in seen[v].neighbors))))
        else:
            out.append("")
    print("\n".join(out))
'),
