('f058ba71-4fb9-43ac-9bf0-a998ad1a6945', '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

/* Report each combination via emit(combo, len). Combinations may be reported in any order. */
static void emit(int * combo, int len);

void combinationSum2(int * candidates, int n, int target) {
    /* TODO: find combinations and call emit(combo, len) for each */
}

/* ---- harness below collects, sorts, and prints; do not modify ---- */
static int ** buf;
static int * lens;
static int cap, cnt;
static int cmp_combo(const void * a,
    const void * b) {
    int ia = * (const int * ) a, ib = * (const int * ) b;
    int la = lens[ia], lb = lens[ib], m = la < lb ? la : lb;
    for (int i = 0; i < m; i++) {
        if (buf[ia][i] != buf[ib][i]) return buf[ia][i] - buf[ib][i];
    }
    return la - lb;
}
static int cmp_int(const void * a,
    const void * b) {
    return ( * (int * ) a) - ( * (int * ) b);
}
static void emit(int * combo, int len) {
    if (cnt == cap) {
        cap = cap ? cap * 2 : 16;
        buf = realloc(buf, cap * sizeof(int * ));
        lens = realloc(lens, cap * sizeof(int));
    }
    int * c = malloc(len * sizeof(int));
    memcpy(c, combo, len * sizeof(int));
    qsort(c, len, sizeof(int), cmp_int);
    buf[cnt] = c;
    lens[cnt] = len;
    cnt++;
}
int main() {
    int n;
    scanf("%d", & n);
    int * cand = malloc((n > 0 ? n : 1) * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", & cand[i]);
    int target;
    scanf("%d", & target);
    combinationSum2(cand, n, target);
    int * idx = malloc((cnt > 0 ? cnt : 1) * sizeof(int));
    for (int i = 0; i < cnt; i++) idx[i] = i;
    qsort(idx, cnt, sizeof(int), cmp_combo);
    for (int i = 0; i < cnt; i++) {
        int k = idx[i];
        for (int j = 0; j < lens[k]; j++) printf("%d%s", buf[k][j], j + 1 < lens[k] ? " " : "");
        printf("\n");
    }
    return 0;
}'),
('f82c179e-87f8-4f4e-89f4-5214970d2a20', 'package main

import(
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)

func combinationSum2(candidates[] int, target int)[][] int {
    // TODO: return all unique combinations (each in ascending order)
    return [][] int {}
}

func main() {
    reader: = bufio.NewReader(os.Stdin)
    var n int
    fmt.Fscan(reader, & n)
    cand: = make([] int, n)
    for i: = 0;i < n;i++{
        fmt.Fscan(reader, & cand[i])
    }
    var target int
    fmt.Fscan(reader, & target)
    res: = combinationSum2(cand, target)
    for _,
    c: = range res {
        sort.Ints(c)
    }
    sort.Slice(res, func(i, j int) bool {
        a,
        b: = res[i],
        res[j]
        m: = len(a)
        if len(b) < m {
            m = len(b)
        }
        for k: = 0;k < m;k++{
            if a[k] != b[k] {
                return a[k] < b[k]
            }
        }
        return len(a) < len(b)
    })
    var lines[] string
    for _,
    c: = range res {
        strs: = make([] string, len(c))
        for i,
        v: = range c {
            strs[i] = fmt.Sprintf("%d", v)
        }
        lines = append(lines, strings.Join(strs, " "))
    }
    fmt.Println(strings.Join(lines, "\n"))
}'),
