    /* TODO */
    return 0;
}

int cmp(const void * a,
    const void * b) {
    return ( * (int * ) a) - ( * (int * ) b);
}

int main() {
    char s[10005];
    if (fgets(s, sizeof(s), stdin) == NULL) s[0] = ''\0'';
    s[strcspn(s, "\r\n")] = ''\0'';
    int nw;
    scanf("%d", & nw);
    static char words[5005][32];
    for (int i = 0; i < nw; i++) scanf("%31s", words[i]);
    int * out = (int * ) malloc(10005 * sizeof(int));
    int cnt = findSubstring(s, words, nw, out);
    qsort(out, cnt, sizeof(int), cmp);
    for (int i = 0; i < cnt; i++) printf("%d%s", out[i], i + 1 < cnt ? " " : "");
    printf("\n");
    return 0;
}'),
