        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] cand = new int[n];
        for (int i = 0; i < n; i++) cand[i] = sc.nextInt();
        int target = sc.nextInt();
        List < List < Integer >> res = combinationSum2(cand, target);
        for (List < Integer > c: res) Collections.sort(c);
        res.sort((a, b) - > {
            int m = Math.min(a.size(), b.size());
            for (int i = 0; i < m; i++)
                if (!a.get(i).equals(b.get(i))) return a.get(i) - b.get(i);
            return a.size() - b.size();
        });
        StringBuilder sb = new StringBuilder();
        for (List < Integer > c: res) {
            for (int i = 0; i < c.size(); i++) sb.append(c.get(i)).append(i + 1 < c.size() ? " " : "");
