('fcfb8ec9-8249-42bc-b30f-c703480b0687', '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

/* Report each subset via emit(subset, len). Subsets may be reported in any order. */
static void emit(int * subset, int len);

void subsetsWithDup(int * nums, int n) {
    /* TODO: generate unique subsets and call emit(subset, len) for each */
}

/* ---- harness: collect, sort by (len, values), print ---- */
static int ** buf;
static int * lens;
static int cap, cnt;
static int cmp_int(const void * a,
    const void * b) {
    return ( * (int * ) a) - ( * (int * ) b);
}
static int cmp_sub(const void * a,
    const void * b) {
    int ia = * (const int * ) a, ib = * (const int * ) b;
    if (lens[ia] != lens[ib]) return lens[ia] - lens[ib];
    for (int i = 0; i < lens[ia]; i++) {
        if (buf[ia][i] != buf[ib][i]) return buf[ia][i] - buf[ib][i];
    }
    return 0;
}
static void emit(int * subset, int len) {
    if (cnt == cap) {
        cap = cap ? cap * 2 : 16;
        buf = realloc(buf, cap * sizeof(int * ));
        lens = realloc(lens, cap * sizeof(int));
    }
    int * c = malloc((len > 0 ? len : 1) * sizeof(int));
    memcpy(c, subset, len * sizeof(int));
    qsort(c, len, sizeof(int), cmp_int);
    buf[cnt] = c;
    lens[cnt] = len;
    cnt++;
}
int main() {
    int n;
    scanf("%d", & n);
    int * nums = malloc((n > 0 ? n : 1) * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", & nums[i]);
    subsetsWithDup(nums, n);
    int * idx = malloc((cnt > 0 ? cnt : 1) * sizeof(int));
    for (int i = 0; i < cnt; i++) idx[i] = i;
    qsort(idx, cnt, sizeof(int), cmp_sub);
    printf("%d\n", cnt);
    for (int i = 0; i < cnt; i++) {
        int k = idx[i];
        for (int j = 0; j < lens[k]; j++) printf("%d%s", buf[k][j], j + 1 < lens[k] ? " " : "");
        printf("\n");
    }
    return 0;
}'),
('55b8ed7e-1a69-4084-ad9d-a17bc850954c', 'package main

import(
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)

func subsetsWithDup(nums[] int)[][] int {
    // TODO: return all unique subsets (each ascending)
    return [][] int {}
}

func main() {
    reader: = bufio.NewReader(os.Stdin)
    var n int
    fmt.Fscan(reader, & n)
    nums: = make([] int, n)
    for i: = 0;i < n;i++{
        fmt.Fscan(reader, & nums[i])
    }
    res: = subsetsWithDup(nums)
    for _,
    s: = range res {
        sort.Ints(s)
    }
    sort.Slice(res, func(i, j int) bool {
        a,
        b: = res[i],
        res[j]
        if len(a) != len(b) {
            return len(a) < len(b)
        }
        for k: = 0;k < len(a);k++{
            if a[k] != b[k] {
                return a[k] < b[k]
            }
        }
        return false
    })
    lines: = [] string {
        fmt.Sprintf("%d", len(res))
    }
    for _,
    s: = range res {
        strs: = make([] string, len(s))
        for i,
        v: = range s {
            strs[i] = fmt.Sprintf("%d", v)
        }
        lines = append(lines, strings.Join(strs, " "))
    }
    fmt.Println(strings.Join(lines, "\n"))
}'),
