vector < vector < int >> subsetsWithDup(vector < int > & nums) {
    // TODO: return all unique subsets (each ascending)
    return {};
}

int main() {
    int n;
    cin >> n;
    vector < int > nums(n);
    for (auto & x: nums) cin >> x;
    auto res = subsetsWithDup(nums);
    for (auto & s: res) sort(s.begin(), s.end());
    sort(res.begin(), res.end(), [](const vector < int > & a,
        const vector < int > & b) {
        if (a.size() != b.size()) return a.size() < b.size();
        return a < b;
    });
    cout << res.size() << "\n";
    for (auto & s: res) {
        for (size_t i = 0; i < s.size(); i++) cout << s[i] << (i + 1 < s.size() ? " " : "");
        cout << "\n";
    }
    return 0;
}'),
('fad655ff-44ae-43ba-9bf0-4ec39b515a3e', 'import java.util.*;

public class Main {
    static List < List < Integer >> subsetsWithDup(int[] nums) {
        // TODO: return all unique subsets (each ascending)
        return new ArrayList < > ();
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();
        List < List < Integer >> res = subsetsWithDup(nums);
        for (List < Integer > s: res) Collections.sort(s);
        res.sort((a, b) - > {
            if (a.size() != b.size()) return a.size() - b.size();
            for (int i = 0; i < a.size(); i++)
                if (!a.get(i).equals(b.get(i))) return a.get(i) - b.get(i);
            return 0;
        });
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append("\n");
        for (List < Integer > s: res) {
            for (int i = 0; i < s.size(); i++) sb.append(s.get(i)).append(i + 1 < s.size() ? " " : "");
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}'),
