('98d56d90-fe74-42e9-981c-f91c0835b8e9', 'import java.io.*;
import java.util.*;

public class Main {
    static String lettersAtIndices(String s, int[] idx) {
        // TODO: return the string characters at the given indices, in order, in lower case
        return "";
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) s = "";
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int n = (int) st.nval;
        int[] idx = new int[n];
        for (int i = 0; i < n; i++) {
            st.nextToken();
            idx[i] = (int) st.nval;
        }
        System.out.println(lettersAtIndices(s, idx));
    }
}'),
