#include <stdlib.h>

#include <string.h>

long long shortest_path_length(int ** graph, int * sizes, int n) {
    // TODO: implement
    return 0;
}

int main() {
    int n;
    scanf("%d", & n);
    getchar();
    int ** graph = malloc(sizeof(int * ) * n);
    int * sizes = malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        char line[2048];
        if (!fgets(line, sizeof(line), stdin)) line[0] = 0;
        int * arr = malloc(sizeof(int) * 64);
        int c = 0;
        char * t = strtok(line, " \t\r\n");
        while (t) {
            arr[c++] = atoi(t);
            t = strtok(NULL, " \t\r\n");
        }
        graph[i] = arr;
        sizes[i] = c;
    }
    printf("%lld\n", shortest_path_length(graph, sizes, n));
    return 0;
}'),
