('e9053790-9db9-4787-8fee-52699cf7048b', '#include <stdio.h>

#include <string.h>

const char * replace_words(char roots[][64], int nr, char sent[][64], int ns) {
    // TODO: implement
    static char res[65536];
    res[0] = 0;
    return res;
}

static int parse(char * line, char arr[][64]) {
    int n = 0;
    char * t = strtok(line, " \t\r\n");
    while (t) {
        strcpy(arr[n++], t);
        t = strtok(NULL, " \t\r\n");
    }
    return n;
}
int main() {
    char la[65536], lb[65536];
    if (!fgets(la, sizeof(la), stdin)) la[0] = 0;
    if (!fgets(lb, sizeof(lb), stdin)) lb[0] = 0;
    char roots[1000][64], sent[1000][64];
    int nr = parse(la, roots), ns = parse(lb, sent);
    printf("%s\n", replace_words(roots, nr, sent, ns));
    return 0;
}'),
