        const node = q.shift();
        if (i < toks.length) {
            const t = toks[i++];
            if (t !== "null") {
                node.left = new TreeNode(parseInt(t, 10));
                q.push(node.left);
            }
        }
        if (i < toks.length) {
            const t = toks[i++];
            if (t !== "null") {
                node.right = new TreeNode(parseInt(t, 10));
                q.push(node.right);
            }
        }
    }
    return root;
}

function _serialize(root) {
    if (!root) return "";
    const out = [];
    const q = [root];
