                String t = toks[i++];
                if (!t.equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(t));
                    q.add(node.left);
                }
            }
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(t));
                    q.add(node.right);
