    string la, lb;
    getline(cin, la);
    getline(cin, lb);
    vector < int > a, b;
    {
        stringstream s(la);
        int x;
        while (s >> x) a.push_back(x);
    } {
        stringstream s(lb);
        int x;
        while (s >> x) b.push_back(x);
    }
    cout << _serialize(build_in_post(a, b)) << endl;
}'),
