('26ebeeae-0196-45dd-ab33-ae0e1c3509f1', 'import sys
from collections import deque
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right
def _build(line):
    toks = line.split()
    if not toks: return None
    root = TreeNode(int(toks[0])); q = deque([root]); i = 1
    while q and i < len(toks):
        node = q.popleft()
        if i < len(toks):
            t = toks[i]; i += 1
            if t != "null": node.left = TreeNode(int(t)); q.append(node.left)
        if i < len(toks):
            t = toks[i]; i += 1
            if t != "null": node.right = TreeNode(int(t)); q.append(node.right)
    return root
def _serialize(root):
    if not root: return ""
    out = []; q = deque([root])
    while q:
        node = q.popleft()
        if node is None: out.append("null")
        else:
            out.append(str(node.val)); q.append(node.left); q.append(node.right)
    while out and out[-1] == "null": out.pop()
    return " ".join(out)

def build_in_post(a, b):
