    return None

if __name__ == "__main__":
    data = sys.stdin.read().split("\n")
    a = list(map(int, data[0].split())) if len(data)>0 else []
    b = list(map(int, data[1].split())) if len(data)>1 else []
    print(_serialize(build_in_post(a, b)))
'),
