('9f2d7f48-6161-4570-9108-b5972078d423', 'import java.util.*;
class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int v) {
        val = v;
    }
}
public class Main {
    static TreeNode build(String line) {
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        Queue < TreeNode > q = new LinkedList < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(t));
                    q.add(node.left);
                }
            }
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(t));
                    q.add(node.right);
                }
            }
        }
        return root;
    }
    static List < Integer > bst_inorder(TreeNode root) {
        // TODO: implement
        return new ArrayList < > ();
    }
    public static void main(String[] x) {
        Scanner sc = new Scanner(System.in);
        String line = sc.hasNextLine() ? sc.nextLine() : "";
        TreeNode root = build(line);
        List < Integer > r = bst_inorder(root);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < r.size(); i++) {
            sb.append(r.get(i));
            if (i + 1 < r.size()) sb.append('' '');
        }
        System.out.println(sb.toString());
    }
}'),
