('7d70d48c-8106-4c6c-8d53-954a982baad1', '#include <bits/stdc++.h>

using namespace std;
struct TreeNode {
    int val;
    TreeNode * left;
    TreeNode * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};
TreeNode * _build(const string & line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty()) return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > left = new TreeNode(stoi(s));
                q.push(node - > left);
            }
        }
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > right = new TreeNode(stoi(s));
                q.push(node - > right);
            }
        }
    }
    return root;
}
string _serialize(TreeNode * root) {
    if (!root) return "";
    vector < string > out;
    queue < TreeNode * > q;
    q.push(root);
    while (!q.empty()) {
        TreeNode * n = q.front();
        q.pop();
        if (!n) out.push_back("null");
        else {
            out.push_back(to_string(n - > val));
            q.push(n - > left);
            q.push(n - > right);
        }
    }
    while (!out.empty() && out.back() == "null") out.pop_back();
    string r;
    for (size_t i = 0; i < out.size(); i++) {
        r += out[i];
        if (i + 1 < out.size()) r += " ";
    }
    return r;
}

TreeNode * flatten(TreeNode * root) {
    // TODO: implement
    return root;
}

int main() {
    string line;
    getline(cin, line);
    TreeNode * root = _build(line);
    cout << _serialize(flatten(root)) << endl;
}'),
('6838d769-681b-451b-b2b4-3a55c1a62070', 'import java.util.*;
class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int v) {
        val = v;
    }
}
public class Main {
    static TreeNode build(String line) {
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        Queue < TreeNode > q = new LinkedList < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(t));
                    q.add(node.left);
                }
            }
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(t));
                    q.add(node.right);
                }
            }
        }
        return root;
    }
    static String serialize(TreeNode root) {
        if (root == null) return "";
        List < String > out = new ArrayList < > ();
        Queue < TreeNode > q = new LinkedList < > ();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode n = q.poll();
            if (n == null) out.add("null");
            else {
                out.add(String.valueOf(n.val));
                q.add(n.left);
                q.add(n.right);
            }
        }
        int e = out.size();
        while (e > 0 && out.get(e - 1).equals("null")) e--;
        return String.join(" ", out.subList(0, e));
    }
    static TreeNode flatten(TreeNode root) {
        // TODO: implement
        return root;
    }
    public static void main(String[] x) {
        Scanner sc = new Scanner(System.in);
        String line = sc.hasNextLine() ? sc.nextLine() : "";
        TreeNode root = build(line);
        System.out.println(serialize(flatten(root)));
    }
}'),
('ab7c6b24-4659-4c72-83c7-bf338424640e', 'import sys
from collections import deque
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val; self.left = left; self.right = right
def _build(line):
    toks = line.split()
    if not toks: return None
    root = TreeNode(int(toks[0])); q = deque([root]); i = 1
    while q and i < len(toks):
        node = q.popleft()
        if i < len(toks):
            t = toks[i]; i += 1
            if t != "null": node.left = TreeNode(int(t)); q.append(node.left)
        if i < len(toks):
            t = toks[i]; i += 1
            if t != "null": node.right = TreeNode(int(t)); q.append(node.right)
    return root
def _serialize(root):
    if not root: return ""
    out = []; q = deque([root])
    while q:
        node = q.popleft()
        if node is None: out.append("null")
        else:
            out.append(str(node.val)); q.append(node.left); q.append(node.right)
    while out and out[-1] == "null": out.pop()
    return " ".join(out)

def flatten(root):
    # TODO: implement; return the (modified) root
    return root

if __name__ == "__main__":
    line = sys.stdin.readline().rstrip("\n")
    root = _build(line)
    print(_serialize(flatten(root)))
'),
