('f6ac9c80-be90-454b-87f4-8bbe324b30ce', '#include <bits/stdc++.h>

using namespace std;
struct TreeNode {
    int val;
    TreeNode * left;
    TreeNode * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};
TreeNode * _build(const string & line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty()) return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > left = new TreeNode(stoi(s));
                q.push(node - > left);
            }
        }
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > right = new TreeNode(stoi(s));
                q.push(node - > right);
            }
        }
    }
    return root;
}
string _serialize(TreeNode * root) {
    if (!root) return "";
    vector < string > out;
    queue < TreeNode * > q;
    q.push(root);
    while (!q.empty()) {
        TreeNode * n = q.front();
        q.pop();
        if (!n) out.push_back("null");
        else {
            out.push_back(to_string(n - > val));
            q.push(n - > left);
            q.push(n - > right);
        }
    }
    while (!out.empty() && out.back() == "null") out.pop_back();
    string r;
    for (size_t i = 0; i < out.size(); i++) {
        r += out[i];
        if (i + 1 < out.size()) r += " ";
    }
    return r;
}

long long kth_smallest(TreeNode * root, int k) {
    // TODO: implement
    return 0;
}

int main() {
    string line;
    getline(cin, line);
    TreeNode * root = _build(line);
    int k;
    cin >> k;
    cout << kth_smallest(root, k) << endl;
}'),
('cbfb696c-b6f9-4448-9dbc-4a7f3fdb98ae', 'import java.util.*;
class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int v) {
        val = v;
    }
}
public class Main {
    static TreeNode build(String line) {
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        Queue < TreeNode > q = new LinkedList < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(t));
                    q.add(node.left);
                }
            }
            if (i < toks.length) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(t));
                    q.add(node.right);
                }
            }
        }
        return root;
    }
    static String serialize(TreeNode root) {
        if (root == null) return "";
        List < String > out = new ArrayList < > ();
        Queue < TreeNode > q = new LinkedList < > ();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode n = q.poll();
            if (n == null) out.add("null");
            else {
                out.add(String.valueOf(n.val));
                q.add(n.left);
                q.add(n.right);
            }
        }
        int e = out.size();
        while (e > 0 && out.get(e - 1).equals("null")) e--;
        return String.join(" ", out.subList(0, e));
    }
    static long kth_smallest(TreeNode root, int k) {
        // TODO: implement
        return 0;
    }
    public static void main(String[] x) {
        Scanner sc = new Scanner(System.in);
        String line = sc.hasNextLine() ? sc.nextLine() : "";
        TreeNode root = build(line);
        int k = Integer.parseInt(sc.nextLine().trim());
        System.out.println(kth_smallest(root, k));
    }
}'),
